theorem ProbabilityTheory.iIndepFun.extracted_1.{u_2, u_1} {Ω : Type u_1} [inst : MeasureSpace Ω] {G : Type u_2}
  [hG : MeasurableSpace G] {Z₁ Z₂ Z₃ : Ω → G} (h_indep : iIndepFun (fun _i => hG) ![Z₁, Z₂, Z₃] ℙ) :
  let σ := { toFun := ![0, 2, 1], invFun := ![0, 2, 1], left_inv := ⋯, right_inv := ⋯ };
  ∀ (x : Ω),
    ((fun {x} => ![Z₁, Z₃, Z₂]) ∘' ⇑σ.symm) ((fun i => i) ⟨2, ⋯⟩) x = ![Z₁, Z₂, Z₃] ((fun i => i) ⟨2, ⋯⟩) x := by
  rfl

